input.command:
node -e '
const fs=require("fs");
const app=JSON.parse(fs.readFileSync("app.json","utf8"));
app.version="1.2.4";
fs.writeFileSync("app.json", JSON.stringify(app,null,2)+"\n");
'
echo '--- app.json after ---'; cat app.json
echo '--- validator after ---'; node scripts/version-check.mjs; echo "exit=$?"
echo '--- hashes ---'; shasum -a 256 scripts/version-check.mjs app.json

